package eval

func campaignInvitationsSuite() Suite {
	base := privacyControlsSuite()
	pendingInvitation := map[string]any{"invitation_id": "invite-player-b", "username": "player-b", "character_id": "play-char-b", "status": "pending"}
	acceptedInvitation := map[string]any{"invitation_id": "invite-player-b", "username": "player-b", "character_id": "play-char-b", "status": "accepted"}
	return Suite{ID: "076-campaign-invitations", Name: "Campaign Play 076: Campaign Invitations", Tests: append(base.Tests,
		playTest("play-invitation-create-campaign", "DM creates a fresh campaign for invitations", "POST", "/v1/play/campaigns", map[string]any{"id": "play-076", "name": "Invitation Campaign", "max_players": 2}, map[string]string{"Authorization": dmAuth}, 201, map[string]any{"id": "play-076", "name": "Invitation Campaign", "owner": "dm", "status": "lobby", "max_players": 2}),
		playTest("play-invitation-join-player-a", "Player A joins the invitation campaign as an unrelated member", "POST", "/v1/play/campaigns/play-076/members", map[string]any{"character_id": "play-char-a", "name": "Aria", "class": "rogue"}, map[string]string{"Authorization": playerAAuth}, 201, map[string]any{"username": "player-a", "character_id": "play-char-a", "name": "Aria", "class": "rogue"}),
		playTest("play-invitation-unauthenticated", "Unauthenticated invitation creation is rejected", "POST", "/v1/play/campaigns/play-076/invitations", map[string]any{"invitation_id": "invite-unauth", "username": "player-b", "character_id": "play-char-b"}, nil, 401, nil),
		playTest("play-invitation-create-player-forbidden", "Players cannot create campaign invitations", "POST", "/v1/play/campaigns/play-076/invitations", map[string]any{"invitation_id": "invite-from-player", "username": "player-b", "character_id": "play-char-b"}, map[string]string{"Authorization": playerAAuth}, 403, nil),
		playTest("play-invitation-empty-id", "Invitation IDs must be nonempty", "POST", "/v1/play/campaigns/play-076/invitations", map[string]any{"invitation_id": "", "username": "player-b", "character_id": "play-char-b"}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-invitation-empty-character", "Invitation character IDs must be nonempty", "POST", "/v1/play/campaigns/play-076/invitations", map[string]any{"invitation_id": "invite-empty-character", "username": "player-b", "character_id": ""}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-invitation-unknown-user", "Invitation targets must be registered players", "POST", "/v1/play/campaigns/play-076/invitations", map[string]any{"invitation_id": "invite-stranger", "username": "stranger", "character_id": "play-char-x"}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTest("play-invitation-dm-user", "Invitation targets cannot be DMs", "POST", "/v1/play/campaigns/play-076/invitations", map[string]any{"invitation_id": "invite-dm", "username": "dm", "character_id": "play-char-dm"}, map[string]string{"Authorization": dmAuth}, 400, nil),
		playTestExactJSON("play-invitation-create", "DM invites registered Player B with a character ID", "POST", "/v1/play/campaigns/play-076/invitations", map[string]any{"invitation_id": "invite-player-b", "username": "player-b", "character_id": "play-char-b"}, map[string]string{"Authorization": dmAuth}, 201, pendingInvitation),
		playTest("play-invitation-duplicate-id", "Duplicate invitation IDs conflict", "POST", "/v1/play/campaigns/play-076/invitations", map[string]any{"invitation_id": "invite-player-b", "username": "player-a", "character_id": "play-char-a2"}, map[string]string{"Authorization": dmAuth}, 409, nil),
		playTest("play-invitation-duplicate-active-user", "Duplicate pending invitations for the same user conflict", "POST", "/v1/play/campaigns/play-076/invitations", map[string]any{"invitation_id": "invite-player-b-again", "username": "player-b", "character_id": "play-char-b2"}, map[string]string{"Authorization": dmAuth}, 409, nil),
		playTestExactJSON("play-invitations-list-dm", "DM sees all campaign invitations", "GET", "/v1/play/campaigns/play-076/invitations", nil, map[string]string{"Authorization": dmAuth}, 200, map[string]any{"invitations": []any{pendingInvitation}}),
		playTestExactJSON("play-invitations-list-target", "Target sees only their own invitation before joining", "GET", "/v1/play/campaigns/play-076/invitations", nil, map[string]string{"Authorization": playerBAuth}, 200, map[string]any{"invitations": []any{pendingInvitation}}),
		playTestExactJSON("play-invitations-list-unrelated-member", "Unrelated campaign members see no invitations", "GET", "/v1/play/campaigns/play-076/invitations", nil, map[string]string{"Authorization": playerAAuth}, 200, map[string]any{"invitations": []any{}}),
		playTest("play-invitation-accept-unknown", "Unknown invitation acceptance returns 404", "POST", "/v1/play/campaigns/play-076/invitations/invite-missing/accept", nil, map[string]string{"Authorization": playerBAuth}, 404, nil),
		playTest("play-invitation-accept-dm-forbidden", "DM cannot accept a player invitation", "POST", "/v1/play/campaigns/play-076/invitations/invite-player-b/accept", nil, map[string]string{"Authorization": dmAuth}, 403, nil),
		playTest("play-invitation-accept-other-player-forbidden", "Other players cannot accept the target invitation", "POST", "/v1/play/campaigns/play-076/invitations/invite-player-b/accept", nil, map[string]string{"Authorization": playerAAuth}, 403, nil),
		playTestExactJSON("play-invitation-accept-target", "Target player accepts and becomes a member with the invited character", "POST", "/v1/play/campaigns/play-076/invitations/invite-player-b/accept", nil, map[string]string{"Authorization": playerBAuth}, 200, acceptedInvitation),
		playTest("play-invitation-accept-repeat", "Accepted invitations cannot be accepted twice", "POST", "/v1/play/campaigns/play-076/invitations/invite-player-b/accept", nil, map[string]string{"Authorization": playerBAuth}, 409, nil),
		playTestExactJSON("play-invitations-list-target-accepted", "Target sees the accepted invitation status", "GET", "/v1/play/campaigns/play-076/invitations", nil, map[string]string{"Authorization": playerBAuth}, 200, map[string]any{"invitations": []any{acceptedInvitation}}),
		playTest("play-invitation-accepted-member-sheet", "Accepted invitation creates the member with supplied character ID", "GET", "/v1/play/campaigns/play-076/characters/play-char-b/sheet", nil, map[string]string{"Authorization": playerBAuth}, 200, map[string]any{"character_id": "play-char-b", "owner": "player-b"}),
	)}
}
